import { test } from "node:test";
import assert from "node:assert/strict";
import { start } from "./helpers.js";

test("a colliding slug is regenerated and the old link is untouched", async () => {
  const slugs = ["aaa", "aaa", "bbb"];
  let calls = 0;
  const app = await start({ randomSlug: () => slugs[calls++], now: () => 5 });
  await app.post("/links", { url: "https://example.com/one" });
  const res = await app.post("/links", { url: "https://example.com/two" });
  assert.equal(res.status, 201);
  assert.equal(res.body.slug, "bbb");
  assert.equal(calls, 3);
  const first = await app.get("/aaa");
  assert.equal(first.headers.get("location"), "https://example.com/one");
  const second = await app.get("/bbb");
  assert.equal(second.headers.get("location"), "https://example.com/two");
  const stats = await app.get("/stats/aaa");
  assert.equal(stats.body.url, "https://example.com/one");
  assert.equal(stats.body.createdAt, 5);
  await app.close();
});

test("invalid url does not call randomSlug", async () => {
  let calls = 0;
  const app = await start({ randomSlug: () => (calls++, "x") });
  const res = await app.post("/links", { url: "nope" });
  assert.equal(res.status, 400);
  assert.equal(calls, 0);
  await app.close();
});
E
